package com.singtel.platformcommon;
import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import java.util.*;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import org.springframework.core.env.Environment;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.slf4j.MDC;
@Component public class RequestContext extends OncePerRequestFilter{private final Environment env;public RequestContext(Environment env){this.env=env;} protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String id=req.getHeader("X-Correlation-ID");if(id==null||!id.matches("[a-zA-Z0-9-]{1,64}"))id=UUID.randomUUID().toString();req.setAttribute("correlationId",id);res.setHeader("X-Correlation-ID",id);MDC.put("correlationId",id);boolean local=env.matchesProfiles("local");if(local){String role=Optional.ofNullable(req.getHeader("X-Demo-Role")).orElse("MANAGER");if(!Set.of("MANAGER","APPROVER","ANALYST","ADMIN").contains(role))role="ANALYST";SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken("demo."+role.toLowerCase(),null,List.of(new SimpleGrantedAuthority("ROLE_"+role))));}try{chain.doFilter(req,res);}finally{MDC.remove("correlationId");if(local)SecurityContextHolder.clearContext();}}}
